const sampleProfiles=[{label:'Sample profile — not a client record',sector:'Sector: to be confirmed',service:'Service: to be confirmed',summary:'Use this card format once a name, sector, project description, and publication approval are available.'},{label:'Sample project summary — draft layout',sector:'Sector: to be confirmed',service:'Service: to be confirmed',summary:'Use this area for an approved overview that describes scope without sharing sensitive details.'},{label:'Sample testimonial slot — optional',sector:'Authorization required',service:'Attribution: to be confirmed',summary:'A quotation should be published only with documented approval from the author and organization.'}];
const services=[
 ['communications','Strategic Corporate Communications','Clear messaging and communication planning for stronger stakeholder understanding.','comm'],['media-pr','Media & Public Relations','Thoughtful media engagement and public relations support for your organization.','media'],['business-innovation','Business Innovation & Development','Practical planning, research, and capacity support for evolving organizations.','business'],['monitoring-evaluation','Monitoring & Evaluation Services','Evidence, learning, and performance insight to inform better decisions.','me'],['smart-techs','Smart Techs','Practical technology approaches for modern, connected organizations.','tech']];
const routeName=location.pathname.replace(/^\/+|\/+$/g,'')||'home';
const page=document.body.dataset.page&&document.body.dataset.page!=='home'?document.body.dataset.page:routeName;
function nav(){let links=`<a href="/">Home</a><a href="/about">About Us</a><details class="drop"><summary>Services</summary><div class="drop-menu">${services.map(s=>`<a href="/${s[0]}">${s[1]}</a>`).join('')}</div></details><a href="/clients">Our Clients</a><a href="/team">Our Team</a><a href="/policies">Our Policies</a><a href="/contact">Contact Us</a>`;return `<a class="skip" href="#main">Skip to content</a><header class="top"><div class="container header"><a href="/" aria-label="Vivacious Consultants home"><img class="logo" src="${A}vivacious_logo-1.jpeg" alt="Vivacious Consultants, Inc. logo"></a><button class="mobile-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Open navigation">☰</button><nav class="nav" id="navigation">${links}</nav><a class="btn talk" href="/contact">Let’s Talk</a></div></header>`}
function footer(){return `<footer class="footer"><div class="container footer-grid"><div><img class="footer-logo" src="${A}vivacious_logo-1.jpeg" alt="Vivacious Consultants, Inc. logo"><p><b>Vivacious Consultants, Inc.</b><br><span data-content="tagline">Local Consultants with the Right Local Content Expertise</span></p><p>A Liberia-based consultancy supporting strategy, communication, innovation, and learning.</p></div><div><h3>QUICK LINKS</h3><ul><li><a href="/">Home</a></li><li><a href="/about">About Us</a></li><li><a href="/clients">Our Clients</a></li><li><a href="/team">Our Team</a></li><li><a href="/contact">Contact Us</a></li></ul></div><div><h3>SERVICES</h3><ul>${services.map(s=>`<li><a href="/${s[0]}">${s[1]}</a></li>`).join('')}</ul></div><div><h3>CONTACT</h3><ul><li><a href="mailto:vivaciousconsultants@gmail.com">vivaciousconsultants@gmail.com</a></li><li><a href="tel:+231886422722">(+231) 886 422 722</a></li><li><a href="tel:+231770943337">(+231) 770 943 337</a></li><li><a href="tel:+231774752626">(+231) 774 752 626</a></li><li><span data-content="office_address">Monrovia, Liberia</span></li></ul><form class="newsletter-form" id="newsletter-form"><label for="newsletter-email">Newsletter updates</label><div><input id="newsletter-email" type="email" required placeholder="Email address"><button type="submit" aria-label="Subscribe">→</button></div><small id="newsletter-status" aria-live="polite"></small></form></div></div><div class="container lower"><span>© ${new Date().getFullYear()} Vivacious Consultants, Inc. All rights reserved.</span><span><a href="/policies#privacy">Privacy Policy</a> &nbsp; <a href="/policies#terms">Terms of Use</a> &nbsp; <a href="/policies">Our Policies</a> &nbsp; <a href="#top">Back to top ↑</a></span></div></footer>`}
function banner(title,key){let noImage=key==='contact';return `<section class="banner ${noImage?'no-image':''}">${noImage?'':`<img src="${image(imgs[key]||imgs.about)}" alt="">`}<div class="container"><div class="crumb"><a href="/">Home</a> / ${title}</div><h1>${title}</h1></div></section>`}
function contactPanel(){return `<section class="section pale"><div class="container contact-panel"><div class="two"><div><h2>Let’s Discuss Your Next Project</h2><p>Tell us what you are working toward. We would be glad to start a conversation.</p><div class="contact-links"><a href="mailto:vivaciousconsultants@gmail.com">vivaciousconsultants@gmail.com</a><a href="tel:+231886422722">(+231) 886 422 722</a></div></div><div><a class="btn orange" href="/contact">Contact Us</a></div></div></div></section>`}
function home(){let slides=[['Local Expertise. Strategic Solutions.','Communications, business development, evaluation, and technology support tailored to your organization.','Explore Our Services','/communications'],['Build Trust. Strengthen Your Voice.','Strategic communications and public relations that connect your organization with the people who matter.','Discover Communications Services','/media-pr'],['Turn Ideas into Practical Progress.','Business innovation and smart technology solutions designed around your goals.','Explore Our Solutions','/business-innovation'],['Measure Results. Inform Decisions.','Monitoring and evaluation support that helps organizations learn, improve, and demonstrate results.','View Evaluation Services','/monitoring-evaluation']];return `<main id="main"><section class="hero" aria-label="Featured services">${slides.map((s,i)=>`<article class="slide ${i===0?'active':''}"><img ${i?'loading="lazy"':'fetchpriority="high"'} src="${image(imgs.hero[i],1600)}" alt="African professionals collaborating in a business setting"><div class="slide-content"><div class="eyebrow">Vivacious Consultants, Inc.</div><h1>${s[0]}</h1><p>${s[1]}</p><div class="hero-actions"><a class="btn" href="${s[3]}">${s[2]}</a>${i===0?'<a class="btn outline" href="/contact">Contact Us</a>':''}</div></div></article>`).join('')}<div class="carousel-controls"><button class="circle previous" aria-label="Previous slide">‹</button><div class="dots">${slides.map((_,i)=>`<button class="dot ${i===0?'active':''}" aria-label="Go to slide ${i+1}"></button>`).join('')}</div><button class="circle next" aria-label="Next slide">›</button><button class="circle play" aria-label="Pause slideshow">Ⅱ</button></div></section><section class="section"><div class="container two"><div class="image-card"><img loading="lazy" src="${image(imgs.about)}" alt="Colleagues in a collaborative workshop"></div><div><div class="kicker">A locally grounded perspective</div><h2 data-content="home_intro_title">Your Partner in Strategy, Communication, and Innovation</h2><p class="muted">Vivacious Consultants supports organizations with strategic communication, public relations, business development, monitoring and evaluation, and practical technology solutions. We bring local context to each conversation and shape our support around what matters to your work.</p><a class="btn" href="/about">About Vivacious</a></div></div></section><section class="section pale"><div class="container"><div class="section-head"><div class="kicker">What we do</div><h2>Focused support for complex work</h2><p class="muted">Explore services designed to help teams communicate clearly, plan practically, and learn from results.</p></div><div class="services">${services.map((s,i)=>`<article class="card"><div class="icon">${['↗','◉','✦','✓','⌘'][i]}</div><h3>${s[1]}</h3><p>${s[2]}</p><a class="link" href="/${s[0]}">Explore service →</a></article>`).join('')}</div></div></section><section class="section"><div class="container"><div class="section-head"><div class="kicker">Our approach</div><h2>Practical from first conversation to next step</h2></div><div class="steps">${['Understand your needs.','Develop a practical strategy.','Support implementation.','Measure and refine results.'].map((x,i)=>`<div class="step"><b>0${i+1}</b><span>${x}</span></div>`).join('')}</div></div></section><section class="section pale"><div class="container"><div class="section-head"><div class="kicker">Why work with us</div><h2>A clear, collaborative way of working</h2></div><div class="values">${['Local context and understanding.','Thoughtful, collaborative engagement.','Practical, results-focused solutions.','Flexible support shaped around your priorities.'].map(x=>`<div class="value"><b>${x}</b></div>`).join('')}</div></div></section><section class="section"><div class="container"><div class="section-head"><div class="kicker">Our clients</div><h2>Built for meaningful partnerships</h2></div><div class="client-empty">Client information will be shared here as approved.<br><a class="link" href="/clients">Visit our clients page →</a></div></div></section><section class="section pale"><div class="container gallery-grid"><div><div class="kicker">Illustrative perspectives</div><h2>Ideas in motion</h2><p class="muted">A look at the collaborative settings that inspire our work. Images are illustrative and do not represent documented client activities.</p><a class="btn" href="/contact">Start a conversation</a></div><div class="gallery">${[imgs.comm,imgs.business,imgs.me].map((x,i)=>`<figure tabindex="0" role="button" aria-label="View gallery image ${i+1}"><img loading="lazy" src="${image(x,600)}" alt="Illustrative consulting and collaboration scene"><figcaption>${['Collaboration','Practical planning','Learning from data'][i]}</figcaption></figure>`).join('')}</div></div></section><section class="section"><div class="container"><div class="feature-band"><div class="kicker" style="color:#83def8">A straightforward next step</div><h2>Start with the question in front of you.</h2><p>Whether you are planning a campaign, refining a strategy, reviewing a program, or considering a digital tool, we can begin with a focused conversation about the context and priorities.</p><a class="btn outline" href="/contact">Let’s Talk</a></div></div></section>${contactPanel()}</main>`}
function about(){return `<main id="main">${banner('About Us','about')}<section class="section about-lead"><div class="container about-hero-grid"><div><div class="kicker">Vivacious Consultants, Inc.</div><h2>Local perspective. Practical thinking. Purposeful support.</h2><p class="lead-copy">We are a Liberia-based consultancy supporting organizations as they communicate, plan, learn, and adapt. Our work brings together strategy, communication, innovation, monitoring and evaluation, and practical technology support.</p><div class="about-actions"><a class="btn" href="/contact">Start a Conversation</a><a class="text-action" href="#what-we-do">Explore What We Do <span>↓</span></a></div><div class="about-mini-stats"><div><b>5</b><span>service areas</span></div><div><b>Local</b><span>context at the center</span></div><div><b>Practical</b><span>next steps in focus</span></div></div></div><div class="about-image-stack"><img loading="lazy" src="${image(imgs.about,1000)}" alt="Illustrative group of professionals collaborating"><div class="image-note"><span>Our focus</span><b>Clear thinking for work that matters.</b></div></div></div></section><section class="section pale" id="what-we-do"><div class="container"><div class="section-head about-center"><div class="kicker">What we do</div><h2>Support that connects the big picture to the next step</h2><p class="muted">We work across connected areas so organizations can bring ideas, evidence, communications, and technology into a more useful whole.</p></div><div class="about-services">${services.map((s,i)=>`<a class="about-service" href="/${s[0]}"><span class="about-service-number">0${i+1}</span><div><h3>${s[1]}</h3><p>${s[2]}</p></div><span class="service-arrow">→</span></a>`).join('')}</div></div></section><section class="section"><div class="container"><div class="about-split"><div class="about-sticky"><div class="kicker">Draft company framework</div><h2>Built to be refined with your approved voice</h2><p class="muted">The following content is intentionally presented as an editable draft. It gives the website a useful structure while waiting for approved company statements.</p></div><div class="draft-cards"><article><span class="card-index">01</span><h3>Mission</h3><p>Sample statement: To provide locally informed consulting support that helps organizations communicate clearly, make practical decisions, and move purposeful work forward.</p></article><article><span class="card-index">02</span><h3>Vision</h3><p>Sample statement: To be a trusted local partner for organizations seeking grounded insight, thoughtful collaboration, and practical innovation.</p></article><article><span class="card-index">03</span><h3>Values</h3><p>Sample themes: local understanding, respect, clarity, collaboration, accountability, and a focus on useful results.</p></article></div></div></div></section><section class="section about-process-section"><div class="container"><div class="section-head"><div class="kicker">How we work</div><h2>A simple, collaborative engagement journey</h2><p class="muted">This is an illustrative working model, adaptable to the scope and context of each assignment.</p></div><div class="about-timeline"><article><span>01</span><h3>Listen and understand</h3><p>Start with priorities, people, context, and the decision or opportunity in front of you.</p></article><article><span>02</span><h3>Shape the approach</h3><p>Identify a focused scope, useful questions, and practical activities that fit the work.</p></article><article><span>03</span><h3>Work alongside you</h3><p>Provide agreed support with clear communication and purposeful collaboration.</p></article><article><span>04</span><h3>Learn and adapt</h3><p>Reflect on progress, capture insight, and identify meaningful next steps.</p></article></div></div></section><section class="section pale"><div class="container about-history"><div><div class="kicker">Our story</div><h2>Company history, ready for your approved narrative</h2><p class="muted">A short timeline can be added here after the company confirms its founding history, milestones, and any public information it would like to share.</p><a class="btn" href="/team">Meet Our Team</a></div><div class="history-placeholder"><span>Editable content area</span><h3>Share the moments that shaped Vivacious.</h3><p>Founding story · milestones · evolution of services · future direction</p></div></div></section>${contactPanel()}</main>`}
const serviceDetail={communications:{intro:'Communication support that helps your organization speak with clarity, consistency, and purpose.',areas:['Communication strategy development','Corporate messaging and positioning','Stakeholder communication','Internal communication','Reputation and issue communication planning','Executive communication support','Communication audits and reviews'],benefit:'Build a shared foundation for messages that people can understand and use.'},'media-pr':{intro:'Thoughtful media and public relations support for organizations planning their public voice.',areas:['Media relations','Press releases and media materials','Media engagement planning','Interview preparation and spokesperson support','Public relations campaigns','Event publicity','Media monitoring and reporting'],benefit:'Prepare clear, timely materials and engagement plans without promising coverage.'},'business-innovation':{intro:'Practical planning and development support for organizations pursuing their next opportunity.',areas:['Business strategy and planning','Market research','Business model development','Organizational development','Partnership development support','Proposal development support','Entrepreneurship and capacity building'],benefit:'Explore opportunities and strengthen planning without promising investment, funding, or contracts.'},'monitoring-evaluation':{intro:'Monitoring and evaluation support that turns data and learning into more informed action.',areas:['Monitoring and evaluation frameworks','Baseline, midline, and endline assessments','Indicators and performance tracking','Survey design and data collection','Data analysis and reporting','Project evaluation','Learning and accountability support'],benefit:'Develop useful evidence and learning processes while respecting sensitive information.'},'smart-techs':{intro:'Practical Technology for Modern Organizations',areas:['Digital transformation advisory','Website and digital platform solutions','Workflow automation','Digital data collection and reporting','Technology adoption support','Digital skills training','Technology-enabled communication'],benefit:'Proposed categories are editable and subject to company approval.'}};
function service(slug){let s=services.find(x=>x[0]===slug), d=serviceDetail[slug];let examples=d.areas.slice(0,3);return `<main id="main">${banner(s[1],s[3])}<section class="section service-intro"><div class="container service-body"><div class="prose"><div class="kicker">Our service</div><h2>${d.intro}</h2><p>Our support is shaped around your priorities, people, and operating context. We work toward steps that are practical, clear, and appropriate for your organization.</p><div class="service-points"><span>Locally informed</span><span>Collaborative approach</span><span>Editable scope</span></div><a class="btn orange" href="/contact?service=${encodeURIComponent(s[1])}">Discuss This Service</a></div><aside class="aside service-aside"><img loading="lazy" src="${image(imgs[s[3]])}" alt="Illustrative ${s[1].toLowerCase()} setting"><div class="aside-caption">Illustrative image · not a documented client activity</div></aside></div></section><section class="section pale"><div class="container"><div class="section-head"><div class="kicker">Scope of support</div><h2>Key service areas</h2><p class="muted">The following areas can be tailored to the question, project, or team in front of you.</p></div><div class="service-area-grid">${d.areas.map((x,i)=>`<article><span>0${i+1}</span><h3>${x}</h3><p>Discuss an appropriate, practical approach for this area of work.</p></article>`).join('')}</div></div></section><section class="section"><div class="container service-delivery"><div><div class="kicker">Illustrative engagement outline</div><h2>What a focused engagement may include</h2><p class="muted">This example is provided to show the structure of a potential assignment. Final outputs, timing, and responsibilities are always agreed with the client.</p><div class="deliverable-list">${examples.map((x,i)=>`<div><b>0${i+1}</b><span>${x}</span></div>`).join('')}</div></div><div class="service-note"><span class="sample-badge">EXAMPLE ONLY</span><h3>A scope shaped around your reality</h3><p>We begin by clarifying the objective, stakeholders, working context, and the useful decision or action the work should support.</p><ul><li>Focused discovery conversation</li><li>Agreed working plan</li><li>Clear progress touchpoints</li></ul></div></div></section><section class="section service-process-wrap"><div class="container"><div class="section-head"><div class="kicker">Our working process</div><h2>From question to useful next step</h2></div><ol class="service-process"><li><b>Discuss</b><span>Share context, priorities, and the decision you are working toward.</span></li><li><b>Define</b><span>Agree a realistic scope, approach, and way of working together.</span></li><li><b>Deliver</b><span>Move through focused activities with clear communication.</span></li><li><b>Reflect</b><span>Review learning and identify meaningful next actions.</span></li></ol></div></section><section class="section pale"><div class="container related-layout"><div><div class="kicker">Common questions</div><h2>Before we begin</h2><div class="service-faq"><details open><summary>Can the scope be adjusted to our needs?</summary><p>Yes. The service areas shown here are a starting point for discussion, not a fixed package.</p></details><details><summary>What information should we prepare?</summary><p>A short overview of your priorities, audience or stakeholders, relevant materials, and desired next step can be helpful.</p></details><details><summary>How do we start a conversation?</summary><p>Use the contact form, email, or telephone details to tell us which service area you would like to discuss.</p></details></div></div><aside><h3>Related services</h3>${services.filter(x=>x[0]!==slug).slice(0,4).map(x=>`<p><a class="link" href="/${x[0]}">${x[1]} →</a></p>`).join('')}<a class="btn" href="/contact?service=${encodeURIComponent(s[1])}">Discuss This Service</a></aside></div></section></main>`}
function clients(){return `<main id="main">${banner('Our Clients','clients')}<section class="section"><div class="container clients-lead"><div><div class="kicker">Partnerships</div><h2>Collaboration built on approved information</h2><p class="muted">We value the opportunity to support organizations working toward meaningful goals. Client names, project details, and testimonials are shared only with appropriate approval.</p><div class="sector-chips"><span>Public sector</span><span>Development organizations</span><span>Businesses</span><span>Community initiatives</span></div></div><div class="client-promise"><b>Our publishing approach</b><p>We do not display client names, logos, outcomes, or quotations without authorization.</p></div></div></section><section class="section pale"><div class="container"><div class="section-head"><div class="kicker">Client profile library</div><h2>Examples of the approved profile format</h2><p class="muted">These sample cards are layout demonstrations only. They do not represent real client records, relationships, or project outcomes.</p></div><div class="sample-grid client-samples">${sampleProfiles.map((p,i)=>`<article class="sample-card"><span class="sample-badge">SAMPLE ${i+1}</span><h3>${p.label}</h3><div class="profile-line"><b>${p.sector}</b><br>${p.service}</div><p>${p.summary}</p><a href="/contact" class="link">Ask about our services →</a></article>`).join('')}</div></div></section><section class="section"><div class="container"><div class="section-head about-center"><div class="kicker">Responsible sharing</div><h2>How a client profile moves from draft to publication</h2></div><div class="approval-flow"><article><span>01</span><h3>Confirm details</h3><p>Agree what information can be publicly shared.</p></article><article><span>02</span><h3>Prepare a draft</h3><p>Frame services and context accurately and concisely.</p></article><article><span>03</span><h3>Request approval</h3><p>Seek authorization from the appropriate contact.</p></article><article><span>04</span><h3>Publish carefully</h3><p>Share only the approved final version.</p></article></div></div></section><section class="section pale"><div class="container client-cta"><div><div class="kicker">Working together</div><h2>Looking for support on a new or evolving priority?</h2><p>Explore our services or begin a conversation about the context of your work.</p></div><div><a class="btn orange" href="/contact">Contact Us</a></div></div></section></main>`}
const initialsPortrait=(initials,color='#08265D')=>`data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="960" viewBox="0 0 800 960"><defs><linearGradient id="g" x1="0" x2="1" y1="0" y2="1"><stop stop-color="${color}"/><stop offset="1" stop-color="#00AFE3"/></linearGradient></defs><rect width="800" height="960" fill="url(#g)"/><circle cx="400" cy="315" r="142" fill="#ffffff24"/><path d="M140 850c30-190 150-280 260-280s230 90 260 280" fill="#ffffff24"/><text x="400" y="540" text-anchor="middle" fill="white" font-family="Arial, sans-serif" font-size="120" font-weight="700">${initials}</text></svg>`)}`;
const teamMembers=[
 {name:'Mr. Samuka Konneh',role:'Chief Executive Director',tag:'Confirmed leadership role',bio:'Mr. Samuka Konneh serves as Chief Executive Director of Vivacious Consultants, Inc. An approved professional biography and portrait can be added here when supplied by the company.',photo:initialsPortrait('SK'),alt:'Profile image placeholder for Mr. Samuka Konneh',pending:true,expertise:['Organizational leadership','Strategic direction','Client engagement']},
 {name:'Amina Johnson',role:'Communications Advisor',tag:'Demo profile — not a staff record',bio:'Demo biography: This sample shows how an approved team member profile can describe communications planning, content development, and stakeholder engagement.',photo:initialsPortrait('AJ','#006E92'),alt:'Illustrative demo profile portrait',expertise:['Messaging','Content planning','Stakeholder engagement']},
 {name:'Daniel K. Brooks',role:'Innovation & Development Associate',tag:'Demo profile — not a staff record',bio:'Demo biography: This sample card demonstrates room for an approved summary of business planning, research, or organizational development support.',photo:initialsPortrait('DB','#335B91'),alt:'Illustrative demo profile portrait',expertise:['Research','Business planning','Capacity support']},
 {name:'Mariama Sesay',role:'Monitoring & Learning Associate',tag:'Demo profile — not a staff record',bio:'Demo biography: This sample card demonstrates room for an approved biography covering data collection, reporting, and learning support.',photo:initialsPortrait('MS','#377C53'),alt:'Illustrative demo profile portrait',expertise:['Data collection','Reporting','Learning support']}
];
function teamCard(m){let i=teamMembers.indexOf(m);return `<article class="team-card ${m.pending?'pending-photo':''}" data-member="${i}"><div class="team-photo"><img loading="lazy" src="${m.photo}" alt="${m.alt}">${m.pending?'<span>Approved portrait pending</span>':''}</div><div class="team-card-body"><div class="member-tag">${m.tag}</div><h3>${m.name}</h3><p class="member-role">${m.role}</p><p>${m.bio}</p><div class="expertise">${m.expertise.map(x=>`<span>${x}</span>`).join('')}</div><div class="member-contact"><a href="mailto:vivaciousconsultants@gmail.com" aria-label="Email Vivacious Consultants about ${m.name}">Email the team</a><a href="tel:+231886422722" aria-label="Call Vivacious Consultants about ${m.name}">Call the office</a></div><button class="profile-open" type="button" aria-haspopup="dialog">View profile & contact <span>→</span></button></div></article>`}
function team(){return `<main id="main">${banner('Our Team','team')}<section class="section"><div class="container"><div class="team-intro"><div><div class="kicker">People</div><h2>Meet the people behind Vivacious</h2><p class="muted">Our team brings locally grounded perspectives to strategy, communication, innovation, monitoring and evaluation, and technology support.</p></div><aside><b>Connect with the team</b><a href="mailto:vivaciousconsultants@gmail.com">vivaciousconsultants@gmail.com</a><a href="tel:+231886422722">(+231) 886 422 722</a></aside></div><div class="team-grid">${teamMembers.map(teamCard).join('')}</div><div class="feature-band"><h2>Interested in working with us?</h2><p>Use our contact page to begin an introduction or ask about the right service for your organization.</p><a class="btn outline" href="/contact">Contact Our Team</a></div></div></section></main>`}
function policies(){let ps=[['privacy','Privacy Policy','Draft pending company review. This section should describe only the personal information this website actually collects, why it is used, how it is protected, and available choices.'],['terms','Website Terms of Use','Draft pending company review. This section will set out the permitted use of website content and related limitations.'],['cookies','Cookie Policy','Draft pending company review. The site does not add nonessential tracking by default; update this section if cookies or analytics are introduced.'],['confidentiality','Confidentiality and Data Handling','Draft pending company review. Describe actual contact submission handling, retention, access, and any approved service providers.'],['accessibility','Accessibility Statement','Draft pending company review. Describe ongoing efforts to make this website usable and a way to request assistance.'],['feedback','Feedback and Complaints','Draft pending company review. Explain a clear route for feedback or concerns after the company confirms a process.']];return `<main id="main">${banner('Our Policies','policy')}<section class="section policy-lead"><div class="container policy-grid"><div><div class="kicker">Policy centre</div><h2>Clear, review-ready policies for a responsible website</h2><p class="muted">The policy framework below is designed to be completed with approved company and operational information before publication as an adopted policy.</p></div><div class="policy-side"><span>Policy status</span><b>Draft collection</b><p>Update after confirming website features, form handling, service providers, and data practices.</p></div></div></section><section class="section pale"><div class="container policy-layout"><aside class="policy-index"><b>ON THIS PAGE</b>${ps.map(p=>`<a href="#${p[0]}">${p[1]}</a>`).join('')}</aside><div><div class="contact-card"><b>Review before publishing</b><br><span class="small">Policy text should be reviewed against the website’s actual data collection, email provider, analytics, cookies, retention, and feedback procedures.</span></div><div class="policies policy-list">${ps.map((p,i)=>`<details id="${p[0]}" ${i===0?'open':''}><summary><span>0${i+1}</span>${p[1]}</summary><p>${p[2]}</p><p class="policy-action">Content checklist: approved wording · responsible owner · last-reviewed date · contact route</p></details>`).join('')}</div></div></div></section><section class="section"><div class="container policy-help"><div><div class="kicker">Questions or feedback</div><h2>Help us improve this website.</h2><p class="muted">Use the contact page to share accessibility feedback, policy questions, or a concern about the website.</p></div><a class="btn" href="/contact">Contact Us</a></div></section></main>`}
function contact(){return `<main id="main">${banner('Contact Us','contact')}<section class="section contact-hero-section"><div class="container contact-overview"><div><div class="kicker">Start a conversation</div><h2 data-content="contact_intro_title">Let’s discuss what is next.</h2><p class="muted">Reach out by email, telephone, or the form. Tell us a little about your priority and the right service area will help guide the conversation.</p><div class="contact-methods"><a href="mailto:vivaciousconsultants@gmail.com"><span>✉</span><div><b>Email us</b><small>vivaciousconsultants@gmail.com</small></div></a><a href="tel:+231886422722"><span>☎</span><div><b>Call us</b><small>(+231) 886 422 722</small></div></a></div></div><div class="contact-expect"><span class="sample-badge">BEFORE YOU SEND</span><h3>A useful introduction includes:</h3><ul><li>The service or challenge you want to discuss</li><li>A little context about your organization or project</li><li>The best contact details for a reply</li></ul></div></div></section><section class="section pale"><div class="container form-wrap"><div class="contact-details-panel"><h3>Contact details</h3><p class="muted">Choose the option that is most convenient for you.</p><div class="contact-detail"><b>Email</b><a href="mailto:vivaciousconsultants@gmail.com">vivaciousconsultants@gmail.com</a></div><div class="contact-detail"><b>Telephone</b><a href="tel:+231886422722">(+231) 886 422 722</a><a href="tel:+231770943337">(+231) 770 943 337</a><a href="tel:+231774752626">(+231) 774 752 626</a></div><div class="contact-detail"><b>Office</b><span data-content="office_address">Monrovia, Liberia</span></div><div class="contact-card"><b>Privacy note</b><br><span class="small">Only share information needed to begin the conversation. Review the draft <a class="link" href="/policies#privacy">Privacy Policy</a> for details pending company approval.</span></div></div><form class="form contact-form-card" id="contact-form" novalidate><div class="form-heading"><div><div class="kicker">Project inquiry</div><h3>Tell us about your project</h3><p>Share a few details and the right member of our team will be able to review your inquiry.</p></div><span>Fields marked * are required</span></div><div class="form-progress" aria-hidden="true"><span></span></div><fieldset class="form-section"><legend>Your details</legend><div class="form-row"><div class="field"><label for="name">Full name *</label><input id="name" name="name" required autocomplete="name" placeholder="Your full name"></div><div class="field"><label for="org">Organization</label><input id="org" name="organization" autocomplete="organization" placeholder="Organization name"></div></div><div class="form-row"><div class="field"><label for="email">Email *</label><input id="email" name="email" required type="email" autocomplete="email" placeholder="you@example.com"></div><div class="field"><label for="phone">Phone</label><input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="Optional"></div></div></fieldset><fieldset class="form-section"><legend>How can we help?</legend><div class="field"><label for="service">Service of interest *</label><select id="service" name="service" required><option value="">Select a service</option><option>General Inquiry</option>${services.map(s=>`<option>${s[1]}</option>`).join('')}</select></div><div class="field"><label for="message">How can we help? *</label><textarea id="message" name="message" required placeholder="Briefly describe your question, project, or priority."></textarea></div></fieldset><p class="small form-privacy">By submitting, you acknowledge the <a class="link" href="/policies#privacy">Privacy Policy</a>.</p><p class="error" id="form-status" aria-live="polite"></p><button class="btn" type="submit">Send Message <span>→</span></button></form></div></section><section class="section"><div class="container"><div class="section-head about-center"><div class="kicker">Frequently asked</div><h2>Helpful information before getting in touch</h2></div><div class="contact-faq"><details open><summary>Which service should I select?</summary><p>Select the closest match. If you are not sure, choose General Inquiry and describe what you would like to discuss.</p></details><details><summary>Can I contact you by telephone instead?</summary><p>Yes. Use any of the telephone links above to call Vivacious Consultants directly.</p></details><details><summary>Is there an office address listed here?</summary><p>No address is displayed until the company supplies and confirms one for public use.</p></details></div></div></section></main>`}
function admin(){return `<main class="admin-page" id="main"><section class="admin-login" id="admin-login"><div class="admin-login-card"><img src="${A}vivacious_logo-1.jpeg" alt="Vivacious Consultants, Inc. logo"><p class="kicker">Secure administration</p><h1>Content & insights</h1><p>Sign in to manage website content, review messages, newsletter subscriptions, and site activity.</p><form id="admin-login-form"><label for="admin-username">Username</label><input id="admin-username" name="username" required autocomplete="username" placeholder="admin"><label for="admin-password">Admin password</label><input id="admin-password" name="password" type="password" required autocomplete="current-password"><p id="admin-login-status" class="error" aria-live="polite"></p><button class="btn" type="submit">Sign in</button></form></div></section><section class="admin-shell" id="admin-shell" hidden><aside class="admin-sidebar"><a href="/" class="admin-brand"><img src="${A}vivacious_logo-1.jpeg" alt="Vivacious Consultants, Inc."></a><p>ADMIN CONSOLE</p><button class="admin-nav active" data-admin-view="overview">Overview</button><button class="admin-nav" data-admin-view="content">Content editor</button><button class="admin-nav" data-admin-view="submissions">Messages & subscribers</button><a href="/" class="admin-site-link">← View website</a><button class="admin-logout" id="admin-logout">Sign out</button></aside><div class="admin-main"><header><div><p class="kicker">Vivacious Consultants</p><h1 id="admin-title">Overview</h1></div><span class="live-dot">Live data</span></header><div id="admin-view"></div></div></section></main>`}
function notFound(){return `<main id="main"><section class="section pale" style="min-height:65vh;display:grid;place-items:center;text-align:center"><div class="container"><p class="kicker">404</p><h1 style="color:#08265D">We could not find that page.</h1><p class="muted">Return home to explore Vivacious Consultants.</p><a class="btn" href="/">Return Home</a></div></section></main>`} let content=page==='home'?home():page==='about'?about():services.some(s=>s[0]===page)?service(page):page==='clients'?clients():page==='team'?team():page==='policies'?policies():page==='contact'?contact():page==='admin'?admin():notFound();document.querySelector('#app').innerHTML=page==='admin'?content:nav()+content+footer();
const toggle=document.querySelector('.mobile-toggle'), navEl=document.querySelector('.nav');function setMenu(open){navEl.classList.toggle('open',open);toggle.setAttribute('aria-expanded',open);toggle.textContent=open?'×':'☰';toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')} toggle?.addEventListener('click',()=>setMenu(!navEl.classList.contains('open')));navEl?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navEl?.classList.contains('open')){setMenu(false);toggle.focus()}});
const current=page==='home'?'/':'/'+page;document.querySelectorAll('.nav a').forEach(a=>{if(a.getAttribute('href')===current)a.classList.add('active')});
const hero=document.querySelector('.hero');if(hero){const slides=[...hero.querySelectorAll('.slide')],dots=[...hero.querySelectorAll('.dot')];let index=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,timer;function show(n){index=(n+slides.length)%slides.length;slides.forEach((x,i)=>x.classList.toggle('active',i===index));dots.forEach((x,i)=>x.classList.toggle('active',i===index))}function stop(){clearInterval(timer);timer=null}function start(){if(!paused){stop();timer=setInterval(()=>show(index+1),6000)}}function interact(){paused=true;stop();let b=hero.querySelector('.play');b.textContent='▶';b.setAttribute('aria-label','Play slideshow')}hero.querySelector('.previous').onclick=()=>{interact();show(index-1)};hero.querySelector('.next').onclick=()=>{interact();show(index+1)};dots.forEach((d,i)=>d.onclick=()=>{interact();show(i)});hero.querySelector('.play').onclick=()=>{paused=!paused;hero.querySelector('.play').textContent=paused?'▶':'Ⅱ';hero.querySelector('.play').setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');paused?stop():start()};hero.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){interact();show(index-1)}if(e.key==='ArrowRight'){interact();show(index+1)}});hero.tabIndex=0;start()}
const box=document.createElement('div');box.className='lightbox';box.innerHTML='<button aria-label="Close image preview">×</button><img alt="Expanded gallery image">';document.body.append(box);document.querySelectorAll('.gallery figure').forEach(f=>{let open=()=>{box.querySelector('img').src=f.querySelector('img').src;box.querySelector('img').alt=f.querySelector('img').alt;box.classList.add('open');box.querySelector('button').focus()};f.onclick=open;f.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')open()}});box.onclick=e=>{if(e.target===box||e.target.tagName==='BUTTON')box.classList.remove('open')};document.addEventListener('keydown',e=>{if(e.key==='Escape')box.classList.remove('open')});
const form=document.querySelector('#contact-form');if(form){let q=new URLSearchParams(location.search).get('service');if(q)form.service.value=q;const status=document.querySelector('#form-status'), progress=form.querySelector('.form-progress span'), required=[...form.querySelectorAll('[required]')], submit=form.querySelector('button[type="submit"]');function updateProgress(){let complete=required.filter(x=>x.value.trim()&&x.checkValidity()).length;progress.style.width=`${Math.round(complete/required.length*100)}%`;if(complete)status.textContent=''}required.forEach(x=>x.addEventListener('input',updateProgress));required.forEach(x=>x.addEventListener('change',updateProgress));updateProgress();form.addEventListener('submit',async e=>{e.preventDefault();if(!form.checkValidity()){status.textContent='Please complete the required fields with a valid email address.';form.reportValidity();return}submit.disabled=true;submit.textContent='Sending…';status.textContent='';try{let r=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),data=await r.json();if(!r.ok)throw new Error(data.error);status.style.color='#18713d';status.textContent=data.message;form.reset();updateProgress()}catch(err){status.style.color='';status.textContent=err.message||'We could not submit your message. Please use the email or telephone details instead.'}finally{submit.disabled=false;submit.innerHTML='Send Message <span>→</span>'}})}
const newsletter=document.querySelector('#newsletter-form');newsletter?.addEventListener('submit',async e=>{e.preventDefault();const status=document.querySelector('#newsletter-status'),button=newsletter.querySelector('button'),email=newsletter.querySelector('input').value;button.disabled=true;try{const r=await fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})}),d=await r.json();if(!r.ok)throw new Error(d.error);status.textContent=d.message;newsletter.reset()}catch(err){status.textContent=err.message||'Please try again later.'}finally{button.disabled=false}});
const visitorKey='vci_visitor';let visitor=localStorage.getItem(visitorKey);if(!visitor){visitor=crypto.randomUUID?.()||String(Date.now());localStorage.setItem(visitorKey,visitor)}fetch('/api/track',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:location.pathname,visitor})}).catch(()=>{});
fetch('/api/content').then(r=>r.json()).then(d=>(d.items||[]).forEach(x=>document.querySelectorAll(`[data-content="${x.content_key}"]`).forEach(el=>el.textContent=typeof x.content_value==='string'?x.content_value:JSON.stringify(x.content_value)))).catch(()=>{});

const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduce&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section,.card,.info-tile,.sample-card').forEach((el,i)=>{if(i>0){el.classList.add('reveal');observer.observe(el)}})}window.addEventListener('scroll',()=>document.querySelector('.top')?.classList.toggle('scrolled',scrollY>12),{passive:true});

// Team member detail dialog: profiles use company-wide contact details until individual details are approved.
const teamCards=[...document.querySelectorAll('.team-card')];
if(teamCards.length){
  const profileDialog=document.createElement('dialog');
  profileDialog.className='profile-dialog';
  profileDialog.innerHTML='<button class="dialog-close" aria-label="Close team member details">×</button><div class="dialog-grid"><div class="dialog-portrait"><img alt=""></div><div class="dialog-content"></div></div>';
  document.body.append(profileDialog);
  let opener=null;
  function showProfile(index,card){
    const m=teamMembers[index]; if(!m)return;
    opener=card;
    profileDialog.querySelector('.dialog-portrait img').src=m.photo;
    profileDialog.querySelector('.dialog-portrait img').alt=m.alt;
    profileDialog.querySelector('.dialog-content').innerHTML=`<div class="member-tag">${m.tag}</div><h2>${m.name}</h2><p class="dialog-role">${m.role}</p><p>${m.bio}</p><h3>Areas of focus</h3><div class="expertise">${m.expertise.map(x=>`<span>${x}</span>`).join('')}</div><h3>Contact</h3><p class="small">Individual contact details are not published. Please use the confirmed Vivacious Consultants contact channels.</p><div class="dialog-contact"><a href="mailto:vivaciousconsultants@gmail.com">Email the team</a><a href="tel:+231886422722">Call (+231) 886 422 722</a></div>`;
    profileDialog.showModal(); profileDialog.querySelector('.dialog-close').focus();
  }
  teamCards.forEach(card=>{card.addEventListener('click',e=>{if(!e.target.closest('a'))showProfile(Number(card.dataset.member),card)})});
  profileDialog.querySelector('.dialog-close').addEventListener('click',()=>profileDialog.close());
  profileDialog.addEventListener('click',e=>{if(e.target===profileDialog)profileDialog.close()});
  profileDialog.addEventListener('close',()=>opener?.focus());
}

// Admin dashboard: the API enforces the signed HttpOnly session; the UI auto-refreshes every 20 seconds.
if(page==='admin'){
 const login=document.querySelector('#admin-login'),shell=document.querySelector('#admin-shell'),view=document.querySelector('#admin-view'),title=document.querySelector('#admin-title');
 const api=(url,opts={})=>fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts}).then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed.');return data});
 const escapeHtml=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
 async function renderDashboard(){const d=await api('/api/admin/dashboard');view.innerHTML=`<div class="admin-stats"><article><span>CONTACT MESSAGES</span><b>${d.stats.contacts}</b><small>All-time submissions</small></article><article><span>NEWSLETTER LIST</span><b>${d.stats.subscriptions}</b><small>Subscribed email addresses</small></article><article><span>PAGE VIEWS</span><b>${d.stats.views30d}</b><small>Last 30 days</small></article></div><div class="admin-panels"><section><div class="panel-head"><h2>Recent messages</h2><button class="admin-nav" data-admin-view="submissions">View all</button></div>${d.recentContacts.length?d.recentContacts.map(x=>`<div class="admin-row"><b>${escapeHtml(x.full_name)}</b><span>${escapeHtml(x.service_interest)}</span><small>${new Date(x.created_at).toLocaleString()}</small></div>`).join(''):'<p class="admin-empty">No contact messages yet.</p>'}</section><section><div class="panel-head"><h2>Recent subscribers</h2><button class="admin-nav" data-admin-view="submissions">View all</button></div>${d.recentSubscriptions.length?d.recentSubscriptions.map(x=>`<div class="admin-row"><b>${escapeHtml(x.email)}</b><small>${new Date(x.created_at).toLocaleString()}</small></div>`).join(''):'<p class="admin-empty">No newsletter subscriptions yet.</p>'}</section></div>`}
 async function renderContent(){const d=await api('/api/admin/content');view.innerHTML=`<div class="admin-toolbar"><div><h2>Content editor</h2><p>Add or update a content key. Current frontend keys include <code>office_address</code>, <code>tagline</code>, <code>home_intro_title</code>, <code>about_intro</code>, and <code>contact_intro_title</code>.</p></div></div><form class="content-form" id="content-form"><label>Content key<input name="key" required maxlength="100" placeholder="office_address"></label><label>Text value<textarea name="value" required placeholder="Monrovia, Liberia"></textarea></label><p id="content-status" class="small" aria-live="polite"></p><button class="btn">Save content</button></form><section class="content-list"><h2>Stored content</h2>${d.items.length?d.items.map(x=>`<article><div><b>${escapeHtml(x.content_key)}</b><span>${escapeHtml(typeof x.content_value==='string'?x.content_value:JSON.stringify(x.content_value))}</span></div><button class="edit-content" data-key="${escapeHtml(x.content_key)}" data-value="${escapeHtml(typeof x.content_value==='string'?x.content_value:JSON.stringify(x.content_value))}">Edit</button></article>`).join(''):'<p class="admin-empty">No custom content records yet.</p>'}</section>`;document.querySelector('#content-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),status=document.querySelector('#content-status');try{await api('/api/admin/content',{method:'PUT',body:JSON.stringify({key:fd.get('key'),value:fd.get('value')})});status.textContent='Saved. Refresh the public page to view the change.';renderContent()}catch(err){status.textContent=err.message}};document.querySelectorAll('.edit-content').forEach(b=>b.onclick=()=>{let f=document.querySelector('#content-form');f.key.value=b.dataset.key;f.value.value=b.dataset.value;f.key.focus()})}
 async function renderSubmissions(){const d=await api('/api/admin/submissions');view.innerHTML=`<div class="submission-tabs"><section><h2>Contact messages</h2>${d.contacts.length?d.contacts.map(x=>`<article class="submission"><div><b>${escapeHtml(x.full_name)}</b><span>${escapeHtml(x.email)} · ${escapeHtml(x.service_interest)}</span></div><p>${escapeHtml(x.message)}</p><small>${new Date(x.created_at).toLocaleString()}</small></article>`).join(''):'<p class="admin-empty">No contact messages yet.</p>'}</section><section><h2>Newsletter subscriptions</h2>${d.subscriptions.length?d.subscriptions.map(x=>`<article class="subscriber"><b>${escapeHtml(x.email)}</b><small>${new Date(x.created_at).toLocaleString()}</small></article>`).join(''):'<p class="admin-empty">No newsletter subscriptions yet.</p>'}</section></div>`}
 const renders={overview:renderDashboard,content:renderContent,submissions:renderSubmissions};
 async function setView(name){document.querySelectorAll('.admin-nav').forEach(b=>b.classList.toggle('active',b.dataset.adminView===name));title.textContent={overview:'Overview',content:'Content editor',submissions:'Messages & subscribers'}[name];try{await renders[name]()}catch(err){view.innerHTML=`<div class="admin-error">${escapeHtml(err.message)}<br><small>Check DATABASE_URL, schema deployment, and your admin session.</small></div>`}}
 document.querySelector('#admin-login-form').onsubmit=async e=>{e.preventDefault();const status=document.querySelector('#admin-login-status');try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({username:e.currentTarget.username.value,password:e.currentTarget.password.value})});login.hidden=true;shell.hidden=false;setView('overview')}catch(err){status.textContent=err.message}};
 document.querySelector('#admin-logout').onclick=async()=>{await fetch('/api/admin/logout',{method:'POST'});shell.hidden=true;login.hidden=false};
 document.querySelectorAll('.admin-nav').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.adminView)));
 setInterval(()=>{if(!shell.hidden)setView(document.querySelector('.admin-nav.active')?.dataset.adminView||'overview')},20000);
}
